1172	// ---------- 多进程写入协调 ----------
1173	//
1174	// 同一数据目录的写请求用目录内的锁文件串行化：取得写入机会后才读取最新已提交
1175	// 状态，业务校验、去重与原子保存（临时文件 + rename）都在持有锁期间完成，因此
1176	// 并发请求的最终结果等价于某个完整串行执行顺序，流水序号与该顺序一致。锁文件
1177	// 位于数据目录内部，相对、绝对及符号链接路径经 realpath 归一后指向同一目录时
1178	// 共用同一把锁；不同目录各有自己的锁，互不阻塞。只读查询不创建也不检查锁文件。
1179	//
1180	// 锁协议（固定闸门 + 按进程命名的身份文件 + 唯一回收协调者）：
1181	//   - 每个写进程先 O_EXCL 创建自己的身份文件
1182	//     .stockroom.json.lock.<pid>.<nonce> 并写完整持有者信息（pid 在“文件名”里，
1183	//     内容在发布前写好），再用 link() 把它硬链接到固定闸门名
1184	//     .stockroom.json.lock：闸门已存在时 link 原子失败（EEXIST），不存在时原子
1185	//     成功，谁也不会覆盖谁。
1186	//   - 判定占用：闸门存在时取其 inode，找到与之同 inode 的身份文件（或协调者
1187	//     文件），其记录的 pid 仍存活就一律等待——哪怕内容暂时不完整，或持有者建锁
1188	//     后暂停很久，文件年龄与内容完整度从不作为接管依据。
1189	//   - 持有者进程退出后闸门成为遗留物。多个等待者先竞争唯一的“回收协调者”文件
1190	//     .stockroom.json.lock.coord（硬链接原子认领，存活期间稳定唯一，死协调者按
1191	//     死 pid 回收）：只有协调者能动闸门。
1192	//   - 接任是一次“只增链接”的原子无缝替换：协调者先把自己的身份文件额外 link 成
1193	//     交接锚点 .stockroom.json.lock.take.<pid>.<nonce>（持有期间稳定保留，作为
1194	//     闸门 inode 的第二硬链接），再 rename(锚点, 闸门) 覆盖旧死闸门。接任者自始
1195	//     至终保留自己身份文件的原名，它是闸门 inode 的稳定硬链接，因此“闸门是否
1196	//     仍属于本请求”始终可凭 inode 判定，不依赖协调者文件内容。
1197	//   - 回收死协调者时绝不凭“先前读到的死 pid”动手：搬走协调者文件后必须重新读
1198	//     回其内容并复核 pid 仍已退出，且该 pid 不是本进程；若文件已被接任者换成
1199	//     新的存活内容（inode/内容已变），立即把刚搬走的文件还原并退出竞争，绝不
1200	//     删除后来者的协调者/闸门。因此两个恢复者即使都已确认旧协调者退出，先接任
1201	//     的一方建立存活占用后，迟到方不可能凭旧判断移走或覆盖它，多个恢复者只能
1202	//     串行取得写入机会。
1203	//   - 接任者在接任 rename 之前或之后再次退出都不影响后续：它的身份/锚点/协调者
1204	//     文件都带自己的死 pid，闸门成为新的遗留占用，下一个写请求自动重复同一
1205	//     回收流程，无需等待或手工删除任何文件。
1206	//   - 释放只作用于本请求的占用：release 只在闸门 inode 仍等于自己身份 inode 时
1207	//     删除闸门，并只删本进程自己的身份/锚点/协调者文件；较早请求的结束、业务
1208	//     失败或超时清理与新请求接任交错时，绝不会删除后来请求的闸门、身份或协调者
1209	//     文件。仍存活的写进程无论写多久都不会被抢占。
1210	//   - 异常退出若发生在原子替换之前，本次业务变动完全不生效；发生在替换之后，
1211	//     完整提交已保留（即使来不及输出成功），重试按已有结果去重。遗留临时文件、
1212	//     身份/锚点/协调者文件与回收物凭 pid 确认持有者已退出后由后续写入者清理，
1213	//     存活请求的文件一律不动。
1214	//
1215	// 等待有上限（默认 10 秒，可用环境变量 STOCKROOM_LOCK_WAIT_MS 按毫秒调整）：
1216	// 只接受十进制非负安全整数，0 表示仅尝试立即取得；非法或超出安全整数范围的
1217	// 配置在任何等待前报标准错误并以退出码 2 结束，绝不退化为无限等待。超时明确
1218	// 报错并以退出码 1 结束。
1219	
1220	const LOCK_GATE = `.${DATA_FILENAME}.lock`; // 固定闸门名（也兼容旧版单文件锁）
1221	const LOCK_COORD = `.${DATA_FILENAME}.lock.coord`; // 回收协调者（稳定、唯一）
1222	const LOCK_PREFIX = `.${DATA_FILENAME}.lock.`; // 各进程身份文件此前缀
1223	const TAKE_PREFIX = `.${DATA_FILENAME}.lock.take.`; // 接任时的交接锚点（身份文件的额外硬链接）
1224	const COORD_PREFIX = `.${DATA_FILENAME}.lock.coord.reclaimed.`; // 死协调者回收物
1225	const RECLAIM_PREFIX = `.${DATA_FILENAME}.lock.reclaimed.`; // 旧版本闸门回收物
1226	const TMP_PREFIX = `.${DATA_FILENAME}.`;
1227	const LOCK_WAIT_DEFAULT_MS = 10_000;
1228	const LOCK_POLL_MS = 50;
1229	const COORD_POLL_MS = 30; // 等待现任回收协调者时的轮询间隔
1230	
1231	interface WriteLock {
1232	  release(): void;
1233	}
1234	
1235	/** 解析并校验等待上限：仅接受纯十进制非负安全整数；0 = 仅立即尝试；非法配置抛用法错误（退出 2）。 */
1236	function lockWaitLimitMs(): number {
1237	  const raw = process.env.STOCKROOM_LOCK_WAIT_MS;
1238	  if (raw === undefined) return LOCK_WAIT_DEFAULT_MS;
1239	  // 必须整体是数字（含空白、小数点、符号均拒绝），避免把非法值悄悄解释为 0 或无限等待
1240	  if (!/^\d+$/.test(raw))
1241	    throw new UsageError(
1242	      `环境变量 STOCKROOM_LOCK_WAIT_MS 必须是非负整数毫秒（0 表示仅尝试立即取得），实际为：${raw}`,
1243	    );
1244	  const n = Number(raw);
1245	  if (!Number.isSafeInteger(n))
1246	    throw new UsageError(
1247	      `环境变量 STOCKROOM_LOCK_WAIT_MS 超出安全整数范围，拒绝启动（不能转换为无限等待）：${raw}`,
1248	    );
1249	  return n;
1250	}
1251	
1252	function pidAlive(pid: number): boolean {
1253	  try {
1254	    process.kill(pid, 0);
1255	    return true;
1256	  } catch (e) {
1257	    return (e as NodeJS.ErrnoException).code === 'EPERM'; // 存在但无权发信号：视为存活
1258	  }
1259	}
1260	
1261	function sleepSync(ms: number): void {
1262	  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
1263	}
1264	
1265	/** 轮询等待某文件出现（仅供确定性回归的同步钩子使用）。 */
1266	function waitForFile(path: string, timeoutMs = 60_000): void {
1267	  const end = Date.now() + timeoutMs;
1268	  for (;;) {
1269	    try {
1270	      statSync(path);
1271	      return;
1272	    } catch {
1273	      if (Date.now() >= end) return;
1274	      sleepSync(10);
1275	    }
1276	  }
1277	}
1278	
1279	/**
1280	 * 仅供本地回归检查使用的确定性同步钩子（未设置 STOCKROOM_TEST_SYNC 时完全无作用）。
1281	 * 配置为单个对象或对象数组：{"point":"<同步点>","signal":"<到达时创建的文件>","wait":"<继续前等待出现的文件>"}。
1282	 * 数组时取第一个 point 匹配的项，便于一个进程在多个同步点上受控。
1283	 * 先 signal 后 wait：到达进程先留下到达标记（内容为其 pid），再阻塞直到测试驱动放行，
1284	 * 从而可精确安排交错，而非靠随机并发碰运气。
1285	 * 同步点：coord-dead（读到旧协调者已死、搬走其文件前）、coord-restore（发现搬走的
1286	 * 是存活接任者、已还原其协调者文件后）、coord-won（当选回收协调者、接任闸门前）、
1287	 * take-before（接任 rename 前）、take-after（接任 rename 后、进入业务前）、
1288	 * release-before（释放闸门前）。
1289	 */
1290	function testSync(point: string): void {
1291	  const raw = process.env.STOCKROOM_TEST_SYNC;
1292	  if (raw === undefined) return;
1293	  let cfgs: Array<{ point?: string; signal?: string; wait?: string }>;
1294	  try {
1295	    const parsed = JSON.parse(raw) as unknown;
1296	    cfgs = Array.isArray(parsed) ? parsed : [parsed];
1297	  } catch {
1298	    return;
1299	  }
1300	  const cfg = cfgs.find((c) => c && c.point === point);
1301	  if (cfg === undefined) return;
1302	  if (cfg.signal) {
1303	    try {
1304	      writeFileSync(cfg.signal, `${process.pid}\n`);
1305	    } catch {
1306	      /* 测试钩子失败不影响正常流程 */
1307	    }
1308	  }
1309	  if (cfg.wait) waitForFile(cfg.wait);
1310	}
1311	
1312	/** 把（可能含符号链接的）数据目录归一为真实路径，使同一目录的不同写法共用一把锁。 */
1313	function resolveDataDir(dataDir: string): string {
1314	  try {
1315	    return realpathSync.native(dataDir);
1316	  } catch {
1317	    // 目录尚不存在：先归一父目录（父目录本身可能是符号链接），再拼上待创建的末级
1318	    const abs = resolve(dataDir);
1319	    const slash = Math.max(abs.lastIndexOf('/'), 0);
1320	    const parent = abs.slice(0, slash) || '/';
1321	    const base = abs.slice(slash + 1);
1322	    try {
1323	      return join(realpathSync.native(parent), base);
1324	    } catch {
1325	      return abs;
1326	    }
1327	  }
1328	}
1329	
1330	/** 读取锁身份文件名中的 pid（.stockroom.json.lock.<pid>.<nonce>）；无法解析返回 null。 */
1331	function lockNamePid(name: string): number | null {
1332	  if (!name.startsWith(LOCK_PREFIX)) return null;
1333	  const rest = name.slice(LOCK_PREFIX.length);
1334	  if (rest === 'coord' || rest.startsWith('coord.')) return null; // 协调者文件，不是任何进程的身份文件
1335	  if (rest.startsWith('take.')) return null; // 接任锚点，由 takeNamePid 解析
1336	  const dot = rest.indexOf('.');
1337	  const part = dot < 0 ? rest : rest.slice(0, dot);
1338	  return /^\d+$/.test(part) ? Number(part) : null;
1339	}
1340	
1341	/** 接任锚点文件名中的 pid（.stockroom.json.lock.take.<pid>.<nonce>）；无法解析返回 null。 */
1342	function takeNamePid(name: string): number | null {
1343	  if (!name.startsWith(TAKE_PREFIX)) return null;
1344	  const rest = name.slice(TAKE_PREFIX.length);
1345	  const part = rest.split('.')[0] ?? '';
1346	  return /^\d+$/.test(part) ? Number(part) : null;
1347	}
1348	
1349	/** 读取协调者文件内容首行记录的 pid；读不到或无法解析返回 null（调用方一律等待，绝不擅动）。 */
1350	function readCoordPid(coordPath: string): number | null {
1351	  try {
1352	    const m = /^(\d+)/.exec(readFileSync(coordPath, 'utf8'));
1353	    if (m === null) return null;
1354	    const pid = Number(m[1]);
1355	    return pid > 0 ? pid : null;
1356	  } catch {
1357	    return null;
1358	  }
1359	}
1360	
1361	/**
1362	 * 尝试成为本目录唯一的“回收协调者”：把本进程的身份文件硬链接到固定协调者名。
1363	 * 返回 true 表示当选；false 表示已有存活协调者（调用方应等待，不得自行回收闸门）。
1364	 * 协调者在整个闸门持有期间保持唯一：其他进程在其存活期间只能等待，从根本上
1365	 * 杜绝两个回收者并发替换闸门。
1366	 *
1367	 * 死协调者的回收严格防止“凭先前判断误删接任者”：搬走协调者文件后必须重新读回
1368	 * 其内容，复核记录的 pid 仍已退出且不是本进程——因为先到的恢复者可能已用同一
1369	 * 协调者名完成接任（coord 仍是闸门 inode 的存活硬链接）。一旦发现搬走的其实是
1370	 * 存活接任者的文件，立即原子还原并退出竞争，迟到者绝不会移走或覆盖后来者刚
1371	 * 建立的占用。
1372	 */
1373	function tryBecomeCoordinator(dir: string, idPath: string): boolean {
1374	  const coordPath = join(dir, LOCK_COORD);
1375	  for (;;) {
1376	    try {
1377	      linkSync(idPath, coordPath);
1378	      // 仅供回归：当选协调者后、接任闸门前崩溃（遗留死协调者 + 旧死闸门）。
1379	      if (process.env.STOCKROOM_TEST_CRASH === 'after-coord') process.kill(process.pid, 'SIGKILL');
1380	      testSync('coord-won'); // 当选（唯一）回收协调者；随后调用方在 gateIsStale 复核后续任
1381	      return true;
1382	    } catch (e) {
1383	      if ((e as NodeJS.ErrnoException).code !== 'EEXIST')
1384	        throw new DataError(`无法获取数据目录写入机会（认领回收协调文件失败）：${(e as Error).message}`);
1385	    }
1386	    // 已有协调者：仅当能确认其 pid 已退出时才考虑回收；任何无法判定的情况一律等待。
1387	    let pid = readCoordPid(coordPath);
1388	    if (pid === null || pid === process.pid || pidAlive(pid)) return false;
1389	    testSync('coord-dead');
1390	    const trash = `${COORD_PREFIX}${process.pid}.${Math.random().toString(36).slice(2)}`;
1391	    const trashPath = join(dir, trash);
1392	    try {
1393	      renameSync(coordPath, trashPath); // 与其他回收死协调者的进程原子决胜
1394	    } catch {
1395	      return false; // 他人已处理：下一轮由 link 的 EEXIST 判定新协调者
1396	    }
1397	    // 关键复核：搬走后重新读取“被搬走的文件”。若它已不是先前那个死协调者
1398	    // （接任者把 coord 换成了自己的存活硬链接，而我们恰好在其接任之后才完成
1399	    // 这次 rename），就必须还原，绝不删除后来者的协调者/闸门。
1400	    const movedPid = readCoordPid(trashPath);
1401	    if (movedPid === null || movedPid === process.pid || pidAlive(movedPid)) {
1402	      try {
1403	        renameSync(trashPath, coordPath); // 原子还原接任者的协调者文件
1404	      } catch {
1405	        /* 还原冲突：对方或他人已在处理；保留回收物绝不强删，交由后续凭 pid 清理 */
1406	      }
1407	      testSync('coord-restore'); // 已确认：先前的“死”判断失效，已把存活接任者的文件还原
1408	      return false;
1409	    }
1410	    try {
1411	      unlinkSync(trashPath);
1412	    } catch {
1413	      /* 忽略；后续 cleanStaleFiles 按死 pid 清理 */
1414	    }
1415	    // 循环回到 link 重试：只有一个进程能成功，其余看到新的存活协调者。
1416	  }
1417	}
1418	
1419	/**
1420	 * 判断固定闸门是否属于已退出的写进程（可安全回收）。
1421	 * 依次按“与闸门同 inode 的文件名”定位属主 pid：
1422	 *   1) 进程身份文件 .stockroom.json.lock.<pid>.<nonce>（新协议，接任也保留原名，
1423	 *      是最稳定的归属锚点）；
1424	 *   2) 接任交接锚点 .stockroom.json.lock.take.<pid>.<nonce>（接任瞬间的额外硬链接）；
1425	 *   3) 协调者文件（pid 记录在内容首行）。
1426	 * 都没有匹配时回退旧式单文件锁内容 pid。归属只取决于这些记录的 pid 是否存活，
1427	 * 内容无法解析则一律视为不可回收，绝不按文件年龄抢占存活进程。
1428	 * 返回 true 可回收；false 为存活占用或无法判定。
1429	 */
1430	function gateIsStale(dir: string): boolean {
1431	  const gatePath = join(dir, LOCK_GATE);
1432	  let gateIno: number | bigint;
1433	  try {
1434	    gateIno = statSync(gatePath).ino;
1435	  } catch {
1436	    return false; // 闸门刚好被释放：调用方下一轮重试即可
1437	  }
1438	  let names: string[];
1439	  try {
1440	    names = readdirSync(dir);
1441	  } catch {
1442	    return false;
1443	  }
1444	  // 1)+2) 身份文件与接任锚点：pid 在文件名里，inode 与闸门相同即属主。
1445	  for (const name of names) {
1446	    const pid = lockNamePid(name) ?? takeNamePid(name);
1447	    if (pid === null) continue;
1448	    try {
1449	      if (statSync(join(dir, name)).ino === gateIno) return !pidAlive(pid);
1450	    } catch {
1451	      /* 文件刚被删除：忽略 */
1452	    }
1453	  }
1454	  // 3) 协调者文件是闸门 inode 的硬链接时，pid 记录在内容首行。
1455	  const coordPid = readCoordPid(join(dir, LOCK_COORD));
1456	  if (coordPid !== null) {
1457	    try {
1458	      if (statSync(join(dir, LOCK_COORD)).ino === gateIno) return !pidAlive(coordPid);
1459	    } catch {
1460	      /* 协调者不存在或不可读：继续旧式回退判定 */
1461	    }
1462	  }
1463	  // 旧式单文件锁：仅当能读到明确且已退出的 pid 才回收
1464	  try {
1465	    const m = /^(\d+) /m.exec(readFileSync(gatePath, 'utf8'));
1466	    if (m === null) return false;
1467	    return !pidAlive(Number(m[1]));
1468	  } catch {
1469	    return false;
1470	  }
1471	}
1472	
1473	/**
1474	 * 取得写入机会后清理异常退出写进程遗留的临时文件、孤立锁身份/接任锚点文件与
1475	 * 各类回收物。只有文件名（或协调者内容）中 pid 已退出的才删除；并且**任何**与
1476	 * 现存闸门同 inode 的文件都绝不删除——那一定是当前占用本身的硬链接（身份、
1477	 * 接任锚点或协调者）。存活等待者的身份文件与现任协调者文件凭存活 pid 一律保留。
1478	 */
1479	function cleanStaleFiles(dir: string): void {
1480	  let names: string[];
1481	  try {
1482	    names = readdirSync(dir);
1483	  } catch {
1484	    return;
1485	  }
1486	  let gateIno: number | bigint | undefined;
1487	  try {
1488	    gateIno = statSync(join(dir, LOCK_GATE)).ino;
1489	  } catch {
1490	    gateIno = undefined;
1491	  }
1492	  for (const name of names) {
1493	    let pidPart: number | null = null;
1494	    if (name.startsWith(TMP_PREFIX) && name.endsWith('.tmp')) {
1495	      const s = name.slice(TMP_PREFIX.length, -'.tmp'.length).split('.')[0];
