  // 临时文件名携带进程号与随机标识：同进程多次保存互不覆盖，崩溃后的遗留文件
  // 也能凭进程号确认持有者已退出后再清理，绝不清除存活请求的临时文件。
  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`);
