      fsyncSync(fd); // 内容落盘后再 rename，保证替换后即完整提交
    } finally {
      closeSync(fd);
    }
    if (crashPoint === 'after-tmp') process.kill(process.pid, 'SIGKILL');
    renameSync(tmp, path);
    if (crashPoint === 'after-rename') process.kill(process.pid, 'SIGKILL');
